import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const EmployeeDashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [vacationDays, setVacationDays] = useState(0);
  const [hasCheckedIn, setHasCheckedIn] = useState(false);
  const [loading, setLoading] = useState(false);
  const [selectedDates, setSelectedDates] = useState([]);
  const [showCalendar, setShowCalendar] = useState(false);

  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem('user'));
    if (!storedUser) {
      navigate('/login');
    } else {
      setUser(storedUser);
      fetchVacationDays(storedUser.id);
      checkIfCheckedIn(storedUser.id);
    }
  }, [navigate]);

  const checkIfCheckedIn = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/checkIn-status`);
      if (!response.ok) throw new Error('Error al verificar check-in');
      const data = await response.json();
      setHasCheckedIn(data.checkedIn);
    } catch (error) {
      console.error('❌ Error al verificar check-in:', error);
    }
  };

  const fetchVacationDays = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/vacation-days`);
      if (!response.ok) throw new Error('Error al obtener días de vacaciones');
      const data = await response.json();
      setVacationDays(data.vacation_days);
    } catch (error) {
      console.error('❌ Error al obtener días de vacaciones:', error);
    }
  };

  const handleCheck = async (type) => {
    setLoading(true);
    if (!navigator.geolocation) {
      alert('❌ Tu navegador no soporta geolocalización.');
      setLoading(false);
      return;
    }

    navigator.geolocation.getCurrentPosition(async (position) => {
      const { latitude, longitude } = position.coords;
      try {
        const response = await fetch(`${API_BASE_URL}/users/${type === 'checkin' ? 'checkIn' : 'checkOut'}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ userId: user.id, latitude, longitude }),
        });

        const data = await response.json();
        if (response.ok) {
          alert(`✅ ${type === 'checkin' ? 'Check-in' : 'Check-out'} registrado correctamente.`);
          setHasCheckedIn(type === 'checkin');
        } else {
          alert(`❌ Error: ${data.error || `Error en el ${type}`}`);
        }
      } catch (error) {
        alert('❌ Error al conectar con el servidor');
      } finally {
        setLoading(false);
      }
    });
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    navigate('/login');
  };

  const handleDateChange = (date) => {
    const dateString = date.toISOString().split('T')[0];
    if (selectedDates.includes(dateString)) {
      setSelectedDates(selectedDates.filter((d) => d !== dateString));
    } else {
      setSelectedDates([...selectedDates, dateString]);
    }
  };

  const handleVacationRequest = async () => {
    if (selectedDates.length === 0) {
      alert('❌ Debes seleccionar al menos un día de vacaciones.');
      return;
    }

    try {
      const response = await fetch(`${API_BASE_URL}/users/${user.id}/vacation-request`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dates: selectedDates }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Error al solicitar vacaciones');
      }

      alert('✅ Vacaciones solicitadas correctamente. Espera la aprobación del administrador.');
      setShowCalendar(false);
      setSelectedDates([]);
      fetchVacationDays(user.id);
    } catch (error) {
      alert(`❌ ${error.message}`);
    }
  };

  const tileDisabled = ({ date }) => {
    const selectedDaysCount = selectedDates.length;
    const remainingDays = vacationDays - selectedDaysCount;
    return date < new Date() || remainingDays <= 0;
  };

  return (
      <div className="flex flex-col items-center py-10 bg-gray-100 min-h-screen">
        {user && <h1 className="text-3xl font-bold text-gray-800">Bienvenido a tu panel, {user.name}</h1>}

        <p className="text-lg mt-4">
          Días de vacaciones disponibles: <strong>{vacationDays}</strong>
        </p>

        <div className="mt-6 flex gap-4">
          {!hasCheckedIn ? (
              <button
                  onClick={() => handleCheck('checkin')}
                  disabled={loading}
                  className={`px-4 py-2 rounded-md text-white font-medium transition-all ${
                      loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-green-500 hover:bg-green-600'
                  }`}
              >
                {loading ? 'Cargando...' : 'Check-in'}
              </button>
          ) : (
              <button
                  onClick={() => handleCheck('checkout')}
                  disabled={loading}
                  className={`px-4 py-2 rounded-md text-white font-medium transition-all ${
                      loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-red-500 hover:bg-red-600'
                  }`}
              >
                {loading ? 'Cargando...' : 'Check-out'}
              </button>
          )}
        </div>

        <button
            onClick={() => setShowCalendar(!showCalendar)}
            disabled={vacationDays === 0}
            className={`mt-6 px-4 py-2 rounded-md text-white font-medium transition-all ${
                vacationDays > 0 ? 'bg-blue-500 hover:bg-blue-600' : 'bg-gray-400 cursor-not-allowed'
            }`}
        >
          Solicitar Vacaciones
        </button>

        {showCalendar && (
            <div className="mt-4 p-4 bg-white shadow-md rounded-md">
              <h2 className="text-lg font-bold mb-2">Selecciona los días de vacaciones</h2>
              <Calendar
                  onChange={handleDateChange}
                  value={selectedDates.map((date) => new Date(date))}
                  tileDisabled={tileDisabled}
                  selectRange={false}
              />
              <button
                  onClick={handleVacationRequest}
                  className="mt-4 px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600"
              >
                Confirmar Selección
              </button>
            </div>
        )}

        <button
            onClick={handleLogout}
            className="mt-8 px-4 py-2 bg-gray-700 text-white rounded-md hover:bg-gray-800 transition-all"
        >
          Cerrar Sesión
        </button>
      </div>
  );
};

export default EmployeeDashboard;
